/**
 * 新版本下好了、验过签（只能手动装的：查到了）
 */
export type UpdateReady = UpdateInfo
/**
 * 仓库里别处发生的变化：文件被外部程序改了，或者一次操作连带改了别的文档
 * （在日历里勾任务，改的是任务所在的那篇）。前端据此刷新缓存。
 */
export type VaultChange = { 
/**
 * 变了（或没了）的笔记 id
 */
notes: string[]; 
/**
 * 变了的某一天（YYYY-MM-DD）
 */
days: string[]; 
/**
 * 变了的目标，`week:2026-09-21`，和前端 goalKey 一样
 */
goals: string[]; 
/**
 * 带日期的任务有变化：日历的当日安排和小圆点要刷新
 */
tasks: boolean; 
/**
 * 这次产生的冲突副本的标题（编辑器里有没存的修改时外部改动到了，另存的那一份）
 */
conflicts: string[]; 
/**
 * 新出现的冲突副本（网盘同步时两边都改过，网盘另存的那一份）的标题
 */
foundCopies: string[]; 
/**
 * 「笔记」下面的文件夹变了（在资源管理器里建了、删了、改了名）
 */
folders: boolean; 
/**
 * 仓库的摆法在别处变了（另一台设备开关了日程、转成了逻辑目录，同步过来）：要按新的摆法重新认文件、
 * 整页重载，前端问一句「切换过去」（vault_relayout）。没切换之前照旧按原来的摆法
 */
layout: boolean }
/**
 * 仓库里别处发生的变化（外部程序改了文件、勾任务改了别的文档），前端据此刷新
 */
export type VaultChanged = VaultChange
/**
 * 启动器左边的一条
 */
export type VaultEntry = { path: string; 
/**
 * 文件夹名
 */
name: string; 
/**
 * 上次打开（Unix 毫秒）
 */
lastOpened: number; 
/**
 * 正在某个窗口里开着
 */
open: boolean; 
/**
 * 文件夹找不到了（移动硬盘没插、被删了、被改名了）
 */
missing: boolean; 
/**
 * 逻辑目录（docs/仓库与启动器.md §7）：列表上前面一个小图标
 */
logical: boolean }
export type VaultInfo = { 
/**
 * 仓库文件夹的绝对路径
 */
root: string; notes: number; archived: number; days: number; goals: number; tasks: number; layout: VaultLayout }
/**
 * 这个仓库怎么摆（vault/layout.rs 的 Layout）：前端据此决定窄栏上有哪几项、一篇笔记在树上哪个文件夹
 */
export type VaultLayout = { 
/**
 * 逻辑目录（docs/仓库与启动器.md §7）：文件树是清单里摆的那一棵（tree_view），不按文件夹
 */
logical: boolean; 
/**
 * 开没开日程（今日TODO、目标、日历、归档）
 */
journal: boolean; 
/**
 * 文件树的根：「笔记」，或者整个仓库（空串）
 */
notesDir: string; daysDir: string; goalsDir: string; archiveDir: string; 
/**
 * 不在树上的文件夹（日程开着时的日记、目标、归档）：里面的笔记算在树根这一层
 */
hiddenDirs: string[] }

/** tauri-specta globals **/

import {
	invoke as TAURI_INVOKE,
	Channel as TAURI_CHANNEL,
} from "@tauri-apps/api/core";
import * as TAURI_API_EVENT from "@tauri-apps/api/event";
import { type WebviewWindow as __WebviewWindow__ } from "@tauri-apps/api/webviewWindow";

type __EventObj__<T> = {
	listen: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.listen<T>>;
	once: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.once<T>>;
	emit: null extends T
		? (payload?: T) => ReturnType<typeof TAURI_API_EVENT.emit>
		: (payload: T) => ReturnType<typeof TAURI_API_EVENT.emit>;
};

export type Result<T, E> =
	| { status: "ok"; data: T }
	| { status: "error"; error: E };

function __makeEvents__<T extends Record<string, any>>(
	mappings: Record<keyof T, string>,
) {
	return new Proxy(
		{} as unknown as {
			[K in keyof T]: __EventObj__<T[K]> & {
				(handle: __WebviewWindow__): __EventObj__<T[K]>;
			};
		},
		{
			get: (_, event) => {
				const name = mappings[event as keyof T];

				return new Proxy((() => {}) as any, {
					apply: (_, __, [window]: [__WebviewWindow__]) => ({
						listen: (arg: any) => window.listen(name, arg),
						once: (arg: any) => window.once(name, arg),
						emit: (arg: any) => window.emit(name, arg),
					}),
					get: (_, command: keyof __EventObj__<any>) => {
						switch (command) {
							case "listen":
								return (arg: any) => TAURI_API_EVENT.listen(name, arg);
							case "once":
								return (arg: any) => TAURI_API_EVENT.once(name, arg);
							case "emit":
								return (arg: any) => TAURI_API_EVENT.emit(name, arg);
						}
					},
				});
			},
		},
	);
}
